Algorithm Cumple
  Define edad As Integer <- 10;
  Write edad;
  edad <- edad + 1;
  Write edad;
EndAlgorithm

Algorithm Caramelos
  Write 47 Div 6, " ", 47 Mod 6;
EndAlgorithm

Algorithm Fiesta
  Define invitados As Integer <- 23;
  Define porcionesPorPersona As Integer <- 3;
  Define porcionesPorPizza As Integer <- 8;
  Define porciones As Integer <- invitados * porcionesPorPersona;
  Write "Pizzas que hay que pedir: ", ceil(porciones / porcionesPorPizza);
EndAlgorithm
